anfangs_states = ({'preiskarten': (1, 2, 3), 'punkte': 0}, )

def naechste_runde(state):
    return {'preiskarten': state['preiskarten'][1:],
            'punkte': state['punkte'] + state['preiskarten'][0]}

def rungame(states):
    if len(states[-1]['preiskarten']) == 0:
        return states
    else:
        return rungame(states + (naechste_runde(states[-1]),))

